/// A plugin source — the unit a host registers as a tool provider.
///
/// Generalizes the host's "saved server" (e.g. AppPlayer's `ServerConfig`)
/// across three substrates. The physical platform reach falls out of the
/// substrate — it is a fact, not a quality ranking:
///
/// | kind     | substrate                                         | reach          |
/// |----------|---------------------------------------------------|----------------|
/// | `bundle` | in-process bundle activation                      | all platforms  |
/// | `server` | a server the person points at (network or process)| network: all · process: desktop |
/// | `hub`    | a server a door (hub / market connect) grants      | all platforms  |
///
/// A `hub` source keeps a [ref] (the listing), never an address or token: the
/// door issues fresh access on every connect.
library;

import 'package:brain_kernel/brain_kernel.dart' show KernelTransportKind;

enum PluginKind { bundle, server, hub }

/// Why a registered plugin is not serving right now.
enum PluginUnavailable {
  /// The address or process cannot be reached.
  unreachable('unreachable'),

  /// The bundle is not in the host's bundle store.
  bundleMissing('bundle-missing'),

  /// The door refused fresh access (subscription ended, refund, policy).
  accessEnded('access-ended'),

  /// The door has nothing to connect to yet (node not attached, server down).
  notReady('not-ready'),

  /// This platform cannot run the source (e.g. a process on a phone).
  gated('gated'),

  /// No recorded consent covers the stored source.
  notApproved('not-approved');

  const PluginUnavailable(this.wire);

  /// Stable name used in lists and error answers.
  final String wire;
}

class PluginSource {
  const PluginSource({
    required this.id,
    required this.kind,
    this.name = '',
    this.description = '',
    this.transport,
    this.endpoint,
    this.options,
    this.ref,
    this.tools,
    this.destructiveTools,
  });

  /// Stable id — also the tool namespace: tools register as `<id>.<tool>`.
  /// It never contains a dot (the dot separates the namespace).
  final String id;

  final PluginKind kind;
  final String name;
  final String description;

  /// Transport for `server`/`hub` kinds. Ignored for `bundle`.
  final KernelTransportKind? transport;

  /// Endpoint (URL / command) for `server` kinds; the bundle location for
  /// `bundle`. Not used by `hub` sources, whose access comes from the door.
  final String? endpoint;

  /// Transport options for `server` kinds. Secret values are referenced
  /// (`credentialRef`), not carried here as plain text.
  final Map<String, dynamic>? options;

  /// Door reference for `hub` sources (a market listing). The access
  /// (endpoint, token, session) is requested again on every connect.
  final String? ref;

  /// Tool names to mirror. Null mirrors every tool the server lists.
  final List<String>? tools;

  /// Tool names registered as destructive, so the host's human-confirm gate
  /// stands in front of their calls.
  final List<String>? destructiveTools;

  /// A source whose access is issued by a door and expires.
  bool get isDoorIssued => ref != null;

  /// A network-reachable source works on every platform; a local subprocess
  /// `server` does not (no process spawn on mobile). The host gates on this.
  bool get isNetwork =>
      transport == KernelTransportKind.streamableHttp ||
      transport == KernelTransportKind.sse;
}
